// Resolutor de Desenvolvimento - Inicialização
// Executa ações corretivas em código e desenvolvimento

const payload = $input.item.json.body || $input.item.json;

return [{
  json: {
    resolver: {
      name: 'Resolutor de Desenvolvimento',
      version: '1.0',
      specialization: ['React', 'TypeScript', 'FastAPI', 'Python', 'Frontend', 'Backend'],
      role: 'Executar ações corretivas em código e desenvolvimento'
    },
    sessionId: payload.sessionId || payload.troubleshootingSessionId,
    timestamp: new Date().toISOString(),
    actionPlan: payload.actionPlan || payload.consolidatedActionPlan || [],
    diagnosis: payload.diagnosis || {},
    issues: payload.issues || [],
    context: payload.context || {},
    status: 'ready'
  }
}];

// Preparar prompt para Claude AI com plano de ação
const data = $input.item.json;

const prompt = `Você é o Resolutor de Desenvolvimento do CredGestor, especializado em executar ações corretivas em código React, TypeScript, FastAPI e Python.

CONTEXTO DA APLICAÇÃO:
- Frontend: React + Vite + TypeScript
- Backend: FastAPI + Python 3.11
- Repositório: GitHub
- Deploy: Docker Swarm na VPS

DIAGNÓSTICO DO TROUBLESHOOTING:
${JSON.stringify(data.diagnosis, null, 2)}

PLANO DE AÇÃO RECEBIDO:
${JSON.stringify(data.actionPlan, null, 2)}

PROBLEMAS IDENTIFICADOS:
${JSON.stringify(data.issues, null, 2)}

SUA TAREFA:
1. Analisar o plano de ação recebido
2. Validar cada ação antes de executar
3. Gerar mudanças de código específicas (se necessário)
4. Gerar comandos para build e deploy
5. Incluir verificações pós-execução
6. Documentar todas as ações executadas
7. Considerar testes antes de deploy

FORMATO DE RESPOSTA (JSON OBRIGATÓRIO):
{
  "validation": {
    "safeToExecute": true,
    "risks": ["risco1", "risco2"],
    "recommendations": ["recomendação1", "recomendação2"],
    "requiresCodeChanges": false
  },
  "executionPlan": [
    {
      "id": 1,
      "actionId": "id_do_plano_original",
      "description": "Descrição da ação",
      "codeChanges": ["arquivo: linha: mudança"],
      "commands": ["comando1", "comando2"],
      "buildCommands": ["npm run build", "docker build ..."],
      "deployCommands": ["docker stack deploy ..."],
      "expectedResult": "Resultado esperado",
      "verification": "Como verificar sucesso",
      "rollback": "Como reverter se falhar",
      "priority": "immediate|high|medium|low"
    }
  ],
  "vpsConnection": {
    "host": "167.235.76.26",
    "user": "root",
    "instructions": "Instruções detalhadas de conexão SSH e acesso ao código"
  },
  "requiresApproval": true
}`;

return [{
  json: {
    ...data,
    prompt: prompt,
    model: $env.LLM_MODEL || 'claude-3-5-sonnet-20241022'
  }
}];

