// Processar resposta do Claude AI
const resolverData = $('Inicializar Resolutor').item.json;
const llmResponse = $input.item.json;

// Extrair texto da resposta
let analysisText = '';
let responseBody = llmResponse.body || llmResponse;
if (typeof responseBody === 'string') {
  try {
    responseBody = JSON.parse(responseBody);
  } catch (e) {
    responseBody = { content: [{ type: 'text', text: responseBody }] };
  }
}

if (responseBody.content && Array.isArray(responseBody.content)) {
  const textContent = responseBody.content.find(c => c.type === 'text');
  analysisText = textContent ? textContent.text : JSON.stringify(responseBody.content);
} else {
  analysisText = JSON.stringify(responseBody);
}

// Parsear JSON da resposta
let executionPlan = {};
let validation = {};
let vpsConnection = {};

try {
  const jsonMatch = analysisText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    executionPlan = parsed.executionPlan || [];
    validation = parsed.validation || {};
    vpsConnection = parsed.vpsConnection || {};
  } else {
    executionPlan = [];
    validation = { safeToExecute: false, error: 'Não foi possível parsear resposta' };
  }
} catch (e) {
  executionPlan = [];
  validation = { safeToExecute: false, error: e.message };
}

return [{
  json: {
    resolver: resolverData.resolver,
    sessionId: resolverData.sessionId,
    timestamp: new Date().toISOString(),
    validation: validation,
    executionPlan: executionPlan,
    vpsConnection: vpsConnection,
    requiresApproval: validation.safeToExecute !== false,
    rawResponse: analysisText.substring(0, 2000)
  }
}];
